from pathlib import Path
p=Path('src/views/reportes/Proforma.vue')
s=p.read_text(encoding='utf-8'); script=s[s.index('<script>'):s.index('<style scoped>')]
template='''<template>
  <div class="quote-page">
    <nav class="quote-actions"><span>Vista de la proforma</span><button class="btn btn-primary" @click="editOpen=true">Modificar productos</button><button class="btn btn-outline-primary" @click="imprimir">Imprimir</button><button class="btn btn-success" @click="enviarWsp">Enviar por WhatsApp</button></nav>
    <b-modal v-model="editOpen" title="Modificar productos de la proforma" size="xl" hide-footer lazy modal-class="quote-product-modal"><proforma-editor v-if="editOpen" :quote-id="idProforma" embedded @cancel="editOpen=false" @saved="editOpen=false;getProforma()" /></b-modal>
    <article id="invoice-container" class="quote-sheet">
      <header class="quote-brand"><img class="quote-art" src="/nuevo/static/images/proforma-header-modern.png" alt="Equipos de seguridad y tecnología" @error="$event.target.style.visibility='hidden'"><img class="quote-logo" src="/resources/images/logo-ticket.png" alt="NEUROSYSTEM"><div class="quote-company"><strong>{{ empresa.RAZONSOCIAL }}</strong><span v-if="empresa.RUC">RUC {{ empresa.RUC }}</span><span v-if="empresa.DIRECCION">{{ empresa.DIRECCION }}</span><span v-if="empresa.TELEFONO || empresa.CELULAR">{{ empresa.TELEFONO }} {{ empresa.CELULAR }}</span></div></header>
      <div class="quote-heading"><div><span class="eyebrow">PROPUESTA COMERCIAL</span><h1>Proforma</h1></div><div class="quote-number"><strong>{{ proforma.Anio }}-{{ proforma.Numero }}</strong><span>Moneda: soles (S/)</span></div></div>
      <section class="quote-details"><div class="quote-client"><span class="eyebrow">PREPARADA PARA</span><h2>{{ proforma.Cliente }}</h2><p><b>Documento:</b> {{ proforma.Documento || '—' }}</p><p><b>Dirección:</b> {{ proforma.ClienteDireccion || '—' }}</p><p><b>Atendido por:</b> {{ proforma.UsuarioReg }}</p></div><dl><div><dt>Fecha de emisión</dt><dd>{{ formatDate(proforma.FechaReg) }}</dd></div><div><dt>Válida hasta</dt><dd>{{ formatDate(fechaHasta) }}</dd></div><div><dt>Forma de pago</dt><dd>Contado</dd></div><div><dt>Entrega</dt><dd>Inmediato</dd></div></dl></section>
      <p v-if="proforma.Descripcion" class="quote-description">{{ proforma.Descripcion }}</p>
      <table class="quote-products"><thead><tr><th class="line-number">N.º</th><th class="product-column">Producto / descripción</th><th class="quantity">Cant.</th><th class="money">Precio unit.</th><th class="money">Importe</th></tr></thead><tbody><tr v-for="(prod,index) in proforma.productos" :key="index"><td class="line-number">{{ index+1 }}</td><td><div class="product-content"><div class="product-photo"><img v-if="prod.Imagen && !missingImages[index]" :src="'/resources/images/productos/'+prod.Imagen" @error="$set(missingImages,index,true)" alt=""><span v-else class="photo-placeholder" aria-label="Sin imagen">◇</span></div><div class="product-copy"><h3>{{ prod.Producto }}</h3><template v-if="hasSpecs(prod)"><p v-if="specNote(prod)">{{specNote(prod)}}</p><ol><li v-for="(item,i) in specItems(prod)" :key="i">{{item}}</li></ol></template><template v-else><p v-for="(detail,i) in [prod.ProductoDesc,prod.ProductoDesc2,prod.ProductoDesc3,prod.Descripcion].filter(Boolean)" :key="i">{{detail}}</p></template></div></div></td><td class="quantity">{{prod.Cantidad}}</td><td class="money"><span v-if="prod.DisabledTotal === 0">S/ {{prod.Precio | moneda}}</span></td><td class="money amount"><template v-if="prod.DisabledTotal === 0">S/ {{(prod.Precio*prod.Cantidad)-prod.Descuento | redondear}}<small v-if="prod.Descuento">Dscto. {{prod.Descuento | moneda('S/ ')}}</small></template></td></tr></tbody></table>
      <section class="quote-summary"><div class="quote-validity"><strong>Gracias por confiar en nosotros</strong><p>Esta propuesta tiene una validez de {{proforma.DiasValidos}} día(s).</p></div><div class="quote-totals"><div><span>Subtotal</span><strong>S/ {{subTotal | redondear}}</strong></div><div v-if="descuento > 0"><span>Descuento</span><strong>S/ {{descuento | redondear}}</strong></div><div class="grand-total"><span>TOTAL</span><strong>S/ {{total | redondear}}</strong></div></div></section>
      <section class="quote-payment"><h2>Información de pago</h2><img src="/resources/images/cuentas.png" alt="Cuentas bancarias de la empresa"></section>
      <footer class="quote-footer"><div><strong>Condiciones de la propuesta</strong><p>Los productos se entregarán en el local comercial.</p></div><div class="quote-signature">Firma / sello de autorización</div></footer>
    </article>
  </div>
</template>
'''
script=script.replace('editOpen:false,','editOpen:false,\n      missingImages:{},').replace('    hasSpecs(prod)',"    formatDate(value){if(!value)return '—';const bits=String(value).substring(0,10).split('-');return bits.length===3?bits.reverse().join('/'):value},\n    hasSpecs(prod)")
